/**
 * financial-snapshot.ts — 财务报表分析
 *
 * 为诊断 Phase 1 提供企业财务健康度快照：
 *   - 利润率分析（毛利率/净利率/EBITDA）
 *   - 现金流状况（运营/投资/融资）
 *   - 同比/环比趋势
 *   - 与团队规模的关联分析（人均收入、人均成本）
 *
 * 数据来源：用户手动输入或从外部系统导入。
 * 所有指标不影响诊断核心逻辑——仅作为"环境变量"辅助诊断推理。
 */
/** 财务条目 */
export interface FinancialEntry {
    /** 期间标识（如 "2026-Q1"） */
    period: string;
    /** 起始日期 */
    startDate: string;
    /** 结束日期 */
    endDate: string;
    /** 收入（元） */
    revenue: number;
    /** 成本（元） */
    cost: number;
    /** 运营费用（元） */
    operatingExpenses: number;
    /** EBITDA（元） */
    ebitda?: number;
    /** 运营现金流（元） */
    operatingCashFlow?: number;
    /** 投资现金流（元） */
    investingCashFlow?: number;
    /** 融资现金流（元） */
    financingCashFlow?: number;
    /** 期末现金余额（元） */
    cashBalance?: number;
    /** 团队人数 */
    headcount: number;
}
/** 财务快照 */
export interface FinancialSnapshot {
    teamId: string;
    entries: FinancialEntry[];
    /** 当期（最新） */
    current: FinancialEntry;
    /** 上一期 */
    previous: FinancialEntry | null;
    /** 毛利率 */
    grossMargin: number;
    /** 净利率 */
    netMargin: number;
    /** 人均收入 */
    revenuePerHead: number;
    /** 人均成本 */
    costPerHead: number;
    /** 同比增长率（收入） */
    revenueYoYGrowth: number | null;
    /** 同比增长率（利润） */
    profitYoYGrowth: number | null;
    /** 现金流健康度评级 */
    cashFlowHealth: 'healthy' | 'tight' | 'critical' | 'unknown';
    /** 生成时间 */
    generatedAt: string;
}
/** 财务健康度对诊断的影响评估 */
export interface FinancialDiagnosisImpact {
    /** 财力压力对团队协作的影响等级 */
    stressImpactLevel: 'none' | 'low' | 'medium' | 'high';
    /** 建议关注的维度 */
    affectedDimensions: string[];
    /** 解释 */
    explanation: string;
}
/** 从财务条目列表计算快照 */
export declare function computeFinancialSnapshot(params: {
    teamId: string;
    entries: FinancialEntry[];
}): FinancialSnapshot;
/** 评估财务状态对团队诊断的影响 */
export declare function assessFinancialImpact(snapshot: FinancialSnapshot): FinancialDiagnosisImpact;
/** 创建空白财务条目（引导用户填写） */
export declare function createEmptyEntry(period: string, startDate: string, endDate: string): FinancialEntry;
/** 验证财务条目完整性 */
export declare function validateEntry(entry: FinancialEntry): {
    valid: boolean;
    errors: string[];
};
